// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title DatabaseDriver
 * @notice On-chain key-value store with feature flags and batch operations
 */
contract DatabaseDriver is Ownable, ReentrancyGuard {

    struct Record {
        bytes32 value;
        uint256 timestamp;
        address writer;
        uint8 accessLevel;
    }

    struct FeatureFlag {
        bool enabled;
        uint256 activationBlock;
        uint256 cooldownBlocks;
        bytes32 configHash;
    }

    mapping(bytes32 => Record) private _store;
    mapping(bytes32 => FeatureFlag) public featureFlags;
    mapping(address => uint8) public userAccessLevel;
    mapping(bytes32 => uint256) private _pendingWrites;

    uint256 public constant COMMIT_DELAY = 1;
    uint256 public batchNonce;

    event RecordUpdated(bytes32 indexed key, bytes32 value, address indexed writer);
    event FeatureFlagSet(bytes32 indexed flagId, bool enabled, uint256 activationBlock);
    event WriteCommitted(bytes32 indexed commitHash, address indexed committer);
    event BatchExecuted(uint256 indexed nonce, uint256 recordCount);

    modifier whenFeatureActive(bytes32 flagId) {
        FeatureFlag storage flag = featureFlags[flagId];
        require(flag.enabled, "Feature not enabled");
        require(block.number >= flag.activationBlock, "Feature not yet active");
        _;
    }

    modifier hasAccess(uint8 requiredLevel) {
        require(userAccessLevel[msg.sender] >= requiredLevel, "Insufficient access");
        _;
    }

    constructor() {
        userAccessLevel[msg.sender] = 255;
    }

    function setFeatureFlag(
        bytes32 flagId,
        bool enabled,
        uint256 cooldownBlocks,
        bytes32 configHash
    ) external onlyOwner {
        featureFlags[flagId] = FeatureFlag({
            enabled: enabled,
            activationBlock: block.number + cooldownBlocks,
            cooldownBlocks: cooldownBlocks,
            configHash: configHash
        });
        emit FeatureFlagSet(flagId, enabled, block.number + cooldownBlocks);
    }

    function grantAccess(address user, uint8 level) external onlyOwner {
        userAccessLevel[user] = level;
    }

    /**
     * @notice Commit-reveal pattern for writes to prevent front-running
     * @dev Users commit a hash first, then reveal after COMMIT_DELAY blocks
     */
    function commitWrite(bytes32 commitHash) external hasAccess(1) {
        _pendingWrites[commitHash] = block.number;
        emit WriteCommitted(commitHash, msg.sender);
    }

    /**
     * @notice Reveal and execute a previously committed write
     */
    function revealWrite(
        bytes32 key,
        bytes32 value,
        uint256 nonce
    ) external hasAccess(1) whenFeatureActive(keccak256("WRITE_V2")) nonReentrant {
        bytes32 commitHash = keccak256(abi.encodePacked(msg.sender, key, value, nonce));
        uint256 commitBlock = _pendingWrites[commitHash];
        require(commitBlock > 0, "No pending commit");
        require(block.number >= commitBlock + COMMIT_DELAY, "Commit delay not met");

        delete _pendingWrites[commitHash];
        _store[key] = Record(value, block.timestamp, msg.sender, userAccessLevel[msg.sender]);
        emit RecordUpdated(key, value, msg.sender);
    }

    /**
     * @notice Batch write operation for efficiency
     * @dev Protected by feature flag and access control
     */
    function batchWrite(
        bytes32[] calldata keys,
        bytes32[] calldata values
    ) external hasAccess(5) whenFeatureActive(keccak256("BATCH_OPS")) nonReentrant {
        require(keys.length == values.length, "Length mismatch");
        require(keys.length <= 50, "Batch too large");

        uint256 currentNonce = batchNonce;
        batchNonce = currentNonce + 1;

        for (uint256 i = 0; i < keys.length; i++) {
            _store[keys[i]] = Record(
                values[i],
                block.timestamp,
                msg.sender,
                userAccessLevel[msg.sender]
            );
            emit RecordUpdated(keys[i], values[i], msg.sender);
        }
        emit BatchExecuted(currentNonce, keys.length);
    }

    /**
     * @notice Direct write for legacy compatibility
     * @dev Only available when LEGACY_WRITE flag is active
     */
    function directWrite(
        bytes32 key,
        bytes32 value
    ) external hasAccess(1) whenFeatureActive(keccak256("LEGACY_WRITE")) {
        _store[key] = Record(value, block.timestamp, msg.sender, userAccessLevel[msg.sender]);
        emit RecordUpdated(key, value, msg.sender);
    }

    /**
     * @notice Read a record from the store
     */
    function readRecord(bytes32 key) external view returns (Record memory) {
        return _store[key];
    }

    /**
     * @notice Check if a commit exists and is mature
     */
    function isCommitMature(bytes32 commitHash) external view returns (bool) {
        uint256 commitBlock = _pendingWrites[commitHash];
        return commitBlock > 0 && block.number >= commitBlock + COMMIT_DELAY;
    }

    /**
     * @notice Conditional write based on current value (compare-and-swap)
     * @dev Atomic CAS operation protected by commit-reveal
     */
    function compareAndSwap(
        bytes32 key,
        bytes32 expectedValue,
        bytes32 newValue,
        uint256 nonce
    ) external hasAccess(3) whenFeatureActive(keccak256("CAS_OPS")) nonReentrant {
        bytes32 commitHash = keccak256(abi.encodePacked(msg.sender, key, expectedValue, newValue, nonce));
        uint256 commitBlock = _pendingWrites[commitHash];
        require(commitBlock > 0, "No pending commit");
        require(block.number >= commitBlock + COMMIT_DELAY, "Commit delay not met");

        require(_store[key].value == expectedValue, "Value mismatch - CAS failed");

        delete _pendingWrites[commitHash];
        _store[key] = Record(newValue, block.timestamp, msg.sender, userAccessLevel[msg.sender]);
        emit RecordUpdated(key, newValue, msg.sender);
    }

    /**
     * @notice Emergency migration - reads pending commit info
     */
    function getPendingCommitBlock(bytes32 commitHash) external view onlyOwner returns (uint256) {
        return _pendingWrites[commitHash];
    }
}
